-- Monster catalog and hunting-ground spawns imported from the reference
-- server (server/monsters_spawns.sql, generated by server/import_monsters).
--
-- Left out: 30 city guard spawns (Guard1, level 200 with 50000 attack;
-- the monster AI has no PK rules yet and would attack every player), and
-- 215 spawns on maps 1762 and 1999, which are not in the maps table.

-- Spawn 2 was the hand-made Twin City Pheasant pack; the catalog's spawn 1
-- covers the same spot, and its own spawn 2 is the next Pheasant pack.
DELETE FROM monster_spawns WHERE id = 2 AND monster_type_id = 1 AND x = 384 AND y = 458;

